export function orderRoutes(store) {const router=Router();router.get('/orders/:id',route(async(req,res)=>{const order=(await store.read('orders')).find(o=>o.id===req.params.id);if(!order)fail(404,'NOT_FOUND','Order not found');res.json(order);}));return router;}
